-- ============================================================================
-- Method Statement Builder — reference data tables
-- ============================================================================
-- Run this in the Supabase SQL editor (Project → SQL Editor → New query).
--
-- Adds the reference-data tables the new "Build Your Method Statement"
-- feature (Office tab) reads from: staff/competencies, PPE, exclusion zones,
-- equipment, SOPs, the fixed policy sections (11.0-29.0), and the known
-- hazards table. These are all read (and occasionally edited) via the app's
-- existing authenticated Supabase session — same `authenticated_all` policy
-- shape already used for job_forms/vehicle_checks/etc in supabase_rls.sql —
-- so this does NOT reopen anon access the way a generic "public read" policy
-- would.
--
-- The saved method statement documents themselves do NOT get a new table —
-- they're stored in the existing `job_forms` table with a quote_ref prefixed
-- 'MSB-...', exactly like Toolbox Talks ('TBT-...') and Audits ('AUD-...').
-- Nothing to run for that part; it just works once job_forms exists (it
-- already does).
-- ============================================================================

create table if not exists ms_staff (
  id text primary key,
  name text not null,
  default_role text not null,
  first_aider boolean not null default false,
  competencies jsonb not null default '[]'::jsonb  -- [{ "name": "...", "expiry": null }]
);

create table if not exists ms_ppe_library (
  id text primary key,
  name text not null
);

create table if not exists ms_exclusion_zone_library (
  id text primary key,
  activity text not null,
  distance text not null
);

create table if not exists ms_equipment_library (
  id text primary key,
  name text not null,
  sound text,
  vibration text
);

create table if not exists ms_sop_library (
  id text primary key,
  category text not null,
  heading text not null,
  description jsonb not null default '[]'::jsonb,   -- array of paragraph strings
  required_ppe jsonb not null default '[]'::jsonb,   -- array of ms_ppe_library ids
  exclusion_zones jsonb not null default '[]'::jsonb -- array of ms_exclusion_zone_library ids
);

create table if not exists ms_fixed_sections (
  n text primary key,        -- section number, e.g. '11.0'
  title text not null,
  paragraphs jsonb not null default '[]'::jsonb
);

create table if not exists ms_known_hazards (
  id serial primary key,
  hazard text not null,
  control text not null,
  sort_order int not null default 0
);

-- Row Level Security ---------------------------------------------------------
-- Same shape as every other table in this app (see supabase_rls.sql):
-- RLS on, single authenticated_all policy, no anon access.

alter table ms_staff                   enable row level security;
alter table ms_ppe_library             enable row level security;
alter table ms_exclusion_zone_library  enable row level security;
alter table ms_equipment_library       enable row level security;
alter table ms_sop_library             enable row level security;
alter table ms_fixed_sections          enable row level security;
alter table ms_known_hazards           enable row level security;

do $$
declare
  t text;
  tables text[] := array[
    'ms_staff', 'ms_ppe_library', 'ms_exclusion_zone_library',
    'ms_equipment_library', 'ms_sop_library', 'ms_fixed_sections',
    'ms_known_hazards'
  ];
begin
  foreach t in array tables loop
    execute format('drop policy if exists "authenticated_all" on public.%I;', t);
    execute format(
      'create policy "authenticated_all" on public.%I for all to authenticated using (true) with check (true);',
      t
    );
  end loop;
end $$;

-- Seed data ------------------------------------------------------------------

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (n) do nothing;

on conflict do nothing;
