insert into ms_exclusion_zone_library (id, activity, distance) values
  ('ez_hedge', 'Hedge/scrub clearing (non-powered hand tools)', 'At least 5m between workers, plus 3m outwith the running line and the maximum slewing radius of any plant in the area.'),
  ('ez_felling', 'Tree felling operations', 'At least 2 tree lengths maintained between workers, machinery, third parties and infrastructure; never directly below on steep slopes.'),
  ('ez_branch', 'Branch removal', 'At least 2 tree lengths maintained between workers, machinery, third parties and infrastructure; never directly below on steep slopes.'),
  ('ez_crosscut', 'Chainsaw cross-cutting and stacking', 'At least 5m between workers, plus 3m outwith the running line and the maximum slewing radius of plant in the area.'),
  ('ez_chipping', 'Wood chipping operations', 'At least 5m between workers, plus 3m outwith the running line. Discharge chute positioned so chippings/debris cannot strike other workers or third parties.'),
  ('ez_excavator', 'Excavator / tracked plant', 'At least 3m outwith the running line and the maximum slewing radius of the machine.'),
  ('ez_refuel', 'Re-fuelling or decanting fuel', 'At least 3m between workers and 3m outwith the running line. Fuel opened/decanted at least 10m from water courses, drains and heat sources.'),
  ('ez_flail', 'Remote-controlled flail mowing', '15m exclusion cone to the front of the machine; 5m minimum between operator and machine at all times.'),
  ('ez_mewp', 'MEWP operations', 'Safe cordon maintained around the worksite by signage, barriers or a lookout; no unauthorised personnel within the working envelope.')
