  ('eq_greenclimber', 'Greenclimber LV800', '110 dB', 'N/A'),
  ('eq_mewp', 'Hinowa 2010 MEWP', '102 dB', 'N/A'),
  ('eq_volvo_excavator', 'Volvo EC145EL Excavator', '110 dB', '0.5 m/s²'),
