insert into ms_sop_library (id, category, heading, description, required_ppe, exclusion_zones) values
  ('sop_powered_hand_tools', 'General', 'Use of Powered Hand Tools', '["All operators are trained and qualified in the use of any powered hand tool they are required to operate. It is the responsibility of the operator and site supervisor to ensure personnel are competent and hold relevant in-date certification.","Operation of any hand tool must be in accordance with the manufacturer''s instructions and applicable industry good practice. Any deviation, including from safe working distances, must be authorised by the site supervisor.","Prior to use, the operator carries out a pre-use check of the machinery to confirm it is free from defect, safety features are present, and it is safe for use.","All personal protective equipment must be worn prior to work commencing. The operator walks the work area prior to starting to identify hazards, and safe working distances are applied in line with industry good practice."]'::jsonb, '["ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_refuelling', 'General', 'Refuelling Procedure (petrol-driven machinery)', '["Petrol is carried in flammable-proof containers secured within vehicles.","Machines are refuelled away from vehicles, visitors and members of the public. Smoking is not permitted during refuelling or operation of the machines.","Fuel is poured from proprietary containers through a funnel into the machine tank. Care is taken to prevent overfilling and spillages; any spillage is cleared up immediately and disposed of correctly.","The fuel container is returned to the van, clamped in position, and the van locked."]'::jsonb, '[]'::jsonb, '["ez_refuel"]'::jsonb),
  ('sop_chainsaw_ground', 'Cutting operations', 'Ground Based Chainsaw Operations', '["Pre-use checks and safe starting procedures are carried out in accordance with FISA301 and HSE INDG317.","Tree felling is carried out in accordance with FISA302: a directional sink cut controls the felling direction, followed by a back cut leaving an adequate hinge so the tree falls in a controlled manner.","Once on the ground, considering tension and compression, branch removal is carried out via snedding or delimbing (FISA303/307), followed by cross-cutting where applicable (FISA304).","The process for dealing with hung-up trees is carried out in strict accordance with FISA301."]'::jsonb, '["ppe_chainsaw_gloves","ppe_chainsaw_trousers","ppe_chainsaw_boots","ppe_visor"]'::jsonb, '["ez_felling","ez_branch","ez_crosscut"]'::jsonb),
  ('sop_tree_climbing', 'Aerial & climbing', 'Tree Climbing Operations', '["Tree climbing is carried out in accordance with AA Technical Guide 1: Tree climbing and aerial rescue.","Tree condition assessments are carried out by the climber to confirm the structure is safe to climb and suitable anchor points can be achieved.","Where anchor points can be tested from ground level this is done with the weight of two climbers; anchors within the tree are, where practical, subject to a full body-weight test.","The climber''s system comprises a primary system long enough to reach the floor and a backup system. A single connection/anchor may be maintained during changeovers only if the operator remains stationary. Climbers remain attached to at least one anchor throughout the climb."]'::jsonb, '["ppe_harness","ppe_helmet"]'::jsonb, '[]'::jsonb),
  ('sop_tools_in_tree', 'Aerial & climbing', 'Use of Tools Within the Tree', '["Tree climbing operations are carried out in accordance with current published good practice.","Prior to hauling any equipment into the tree, the climber ensures their drop zone is clear and no operator remains directly below.","The climber receives any tool in the tree, attaching it to their harness or dedicated tool line before removing it from the hauling system. The primary and backup system must be in place prior to any machinery use, including handsaws.","The climber decides on the type of cut to be used and confirms the cutting tool is suitable for the dimensions of the timber. Cuts are performed to good practice and BS3998. Once cutting is complete, the chainbrake is applied and the machine turned off, or hand tools returned to their scabbard."]'::jsonb, '["ppe_harness","ppe_chainsaw_gloves"]'::jsonb, '[]'::jsonb),
  ('sop_dismantling_rigging', 'Aerial & climbing', 'Dismantling / Rigging', '["Work methods for tree climbing and use of tools in the tree apply throughout dismantling/rigging operations.","The climber selects anchor points suitable for the rigging system and intended task.","Sections are securely attached to the rigging system by the climber, who directs groundstaff on the anticipated direction of fall and intended outcome.","Groundstaff use a ground-based lowering system to control descending branches, returning the rigging line to the climber after each piece. Where spikes are used, the climber is secured to the tree in accordance with the tree climbing work method."]'::jsonb, '["ppe_harness","ppe_chainsaw_gloves"]'::jsonb, '["ez_branch"]'::jsonb),
  ('sop_chainsaw_from_mewp', 'Aerial & climbing', 'Use of a Chainsaw from a MEWP', '["The climber ensures their drop zone is clear and no operator remains directly below before cutting.","Machinery is started in accordance with AA Technical Guide Two: Safe Use of Tools in the Tree.","The climber decides on the type of cut and confirms the cutting tool is suitable for the dimensions of the timber, performed to good practice and BS3998.","Once cutting is complete, the chainbrake is applied and the machine turned off, and hand tools returned to their scabbard."]'::jsonb, '["ppe_harness","ppe_chainsaw_gloves","ppe_visor"]'::jsonb, '["ez_mewp"]'::jsonb),
  ('sop_extendable_long_reach', 'Aerial & climbing', 'Extendable and Long Reach Tools', '["A safe method of operation is agreed to ensure a safe working distance can be maintained between workers, and between workers and machinery.","Equipment is visually inspected prior to use to confirm safety features are present and functioning; defective equipment is immediately withdrawn from service.","Equipment can be extended as required, assembled a section at a time with the tool turned off during assembly. Where the tree form allows, branches are cut starting at the bottom to allow arisings to free fall.","Control is maintained by not over-extending the operator''s reach, using the minimal number of rods required, and by a second person assisting with stabilisation where the tool is not engine or battery driven. Cutting tools are not used greater than 60° from horizontal. If equipment becomes trapped, it is switched off before any attempt is made to free it."]'::jsonb, '["ppe_gloves"]'::jsonb, '[]'::jsonb),
  ('sop_pruning_head', 'Grounds maintenance', 'Pruning Head', '["Only use the pruning head on small material — do not overstrain the cord.","Place the head carefully and complete formative pruning accurately.","Always stand in a position to avoid any falling branch sections, and be aware that material may try to slide down the shaft towards the operator.","Use an assistant to pull the cord if the site or work is awkward or of long duration."]'::jsonb, '["ppe_eye"]'::jsonb, '[]'::jsonb),
  ('sop_pole_saw', 'Grounds maintenance', 'Pole Saw', '["Branches are assessed for tension and compression forces; material is not cut at a size, length or weight that will jam the blade, strip bark back to the stem, or cause loss of control.","The extension is set to the correct length. A work position is adopted at a distance from the cutting point where no material can drop, deflect or slide down the rod toward the operator.","The saw blade is placed at the correct position, making sure it does not hit other branches, and allowed to seat into the cut using a smooth cutting action without forcing it.","The back is kept straight, avoiding twisting and over-stretching. Pruning follows the 1-2-3 cut method (undercut, top cut, final cut) to BS3998."]'::jsonb, '["ppe_eye"]'::jsonb, '[]'::jsonb),
  ('sop_hand_fed_chipper', 'Machinery & plant', 'Hand Fed Woodchipper Use', '["Woodchipper operations are carried out in accordance with FISA604.","The discharge chute is positioned so as not to create a hazard to operators, third parties or the environment.","Material fed into the woodchipper is of an appropriate size and free from foreign objects.","Brushwood is fed ''butt'' end first; a push stick of at least 1.5m is used to guide material into the feed rollers when needed. No part of the operator''s body enters the infeed hopper while the machine is running."]'::jsonb, '["ppe_hearing","ppe_visor"]'::jsonb, '["ez_chipping"]'::jsonb),
  ('sop_crane_fed_chipper', 'Machinery & plant', 'Crane Fed Woodchipper Use', '["Operators brief themselves on the method statement in place for the task; where doubt exists over safe working practices, work stops and the operator contacts the employer or representative.","A safe method of operation is agreed ensuring a safe working distance can be maintained between workers and machinery, out of the risk zones of the machines being used.","A walk-through of the site is undertaken before works start to identify hazards such as powerlines when setting the machine''s safe working distance. A designated responsible person knows the daily work programme and an emergency contact procedure is agreed.","Warning and prohibition signs are erected on all reasonably foreseeable approaches. The operator inspects ground conditions before deploying stabilisers and selects as firm a surface as possible. The discharge chute is positioned to prevent chips being blown onto the highway or towards other operators or the public, and material to be chipped is checked to be free from stones, metal and foreign objects."]'::jsonb, '["ppe_hearing","ppe_visor"]'::jsonb, '["ez_chipping"]'::jsonb),
  ('sop_remote_flail', 'Machinery & plant', 'Remote Controlled Flail', '["Machinery is only operated in accordance with the manufacturer''s guidance. Operators never ride, or allow others to ride, on the machine.","When not in use the machine is parked on firm level ground with the cutting head resting on the ground and the starting key removed. Operators never operate the machine when their vision is blocked, and the maximum slope angle for safe operation is followed.","Flailing is never carried out directly in line with the operator or third parties. Operators never stand directly below a machine that is operating or parked on a slope, and a safe working distance of at least 5m is maintained.","Flails are subject to a 15m exclusion zone extended in a cone from the front of the machine. Machinery is only used in areas unauthorised personnel/public cannot access, and mowing takes place only parallel to highways."]'::jsonb, '["ppe_hearing","ppe_visor"]'::jsonb, '["ez_flail"]'::jsonb),
  ('sop_tree_shear_grapple', 'Machinery & plant', 'Tree Shear / Grapple Saw', '["The operator inspects the lifting area with the client to confirm its suitability, including for stabilisers/outriggers. If not satisfied, work does not proceed and the site supervisor liaises with the client.","The site supervisor ensures exclusion zones are demarcated with barrier fencing, including the potential drop zone and the route between pick and set-down areas. Pre-use checks of the machine and attachments are carried out, confirming load sensing equipment and display are operational.","The machine is set up with stabiliser mats/pads as required. A dry run confirms the cutting attachment can reach the required height and radius and that the route is unobstructed. The machine is always operated in accordance with manufacturer guidance, including seatbelt use.","Taller and thicker trees are processed into short sections to prevent the carrier vehicle tipping, with the weight of each section estimated against the load ratings before removal. Post-works, dirt and foreign bodies are removed and any damage or fault is reported immediately to the site supervisor."]'::jsonb, '["ppe_hearing"]'::jsonb, '["ez_excavator"]'::jsonb),
  ('sop_forwarder_timber_loading', 'Machinery & plant', 'Forwarder / Timber Loading', '["The operator ensures the loading or parking brake is on while loading and released before moving.","The loader is not operated if any part of the machine or its load can come within one tree length plus the vicinity zone (minimum 15m) of energised overhead power lines. If safe working distances are not clearly identified, operators stop work and seek clarification from the site supervisor.","Work stops immediately if any person or machine enters the specified risk zone. On sloping ground, the machine is parked straight up and down the slope, using stumps or ground obstructions to chock wheels where needed.","When loading, the grapple jaws fully encircle the load, the bunk is loaded evenly and not overloaded, and material is not loaded above the headboard/stanchions. Stacked material is made and maintained in a safe, stable condition on firm ground or bearers."]'::jsonb, '["ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_stump_grinding', 'Machinery & plant', 'Stump Grinding', '["The site is checked for underground services before breaking ground; a permit to dig is issued where required and any CAT/GENNY operator is competent and the machine calibrated.","The stump is checked and free from stones and metal so far as reasonably practicable, and buttress roots are manually excavated and revealed.","The machine is operated from a point giving a clear view of the cutting operation. The cutting mechanism is never approached until it has come to a complete stop.","Excavations are checked to ensure they do not create a tripping hazard once the operation is complete. When leaving the machine unattended the engine start key is always removed."]'::jsonb, '["ppe_visor","ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_compact_loader', 'Machinery & plant', 'Compact Loader', '["No one rides on the machine unless in a designated seat with a seatbelt fitted and worn. The machine is not used on the public highway.","Operators are advised to walk the route the machinery is to take before travelling across a site to identify hazards. When moving on a slope, the weight of the machine is kept uphill where possible and turning on slopes is avoided.","The minimum distance maintained between the machine and a fixed obstacle is 600mm. The machine is not overloaded, speeds are kept low, and sharp turns and slope travel are avoided. The stated Safe Working Load is never exceeded.","Loads are approached square on and kept even and level; the operator visually checks the area is clear before moving off with a load. A seatbelt is worn and the horn used to warn others of movement. Machinery is parked per manufacturer guidance with keys removed when left unattended, never on slopes."]'::jsonb, '["ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_mewp', 'Machinery & plant', 'MEWP (Mobile Elevated Work Platform)', '["Safe methods of working are agreed by operatives on site, including access checks and ground condition checks before the platform is raised.","Operators establish a safe cordon around the worksite, maintained by signs, barriers or a lookout where practical.","The operative''s harness is securely attached to a designated anchor point in the MEWP bucket prior to the boom being raised. The Safe Working Load (SWL) must not be exceeded.","Only one operative works in the bucket at a time unless separated by a physical barrier, in which case a second operative is present to carry out rescue if required. Tasks are carried out in accordance with the AA Technical Guide: Safe use of MEWPs in tree work."]'::jsonb, '["ppe_harness","ppe_helmet"]'::jsonb, '["ez_mewp"]'::jsonb),
  ('sop_strimmer', 'Grounds maintenance', 'Strimmer', '["Operators inspect the work area before starting, to remove or clearly mark any hazards that may pose a risk.","Pre-start checks confirm safety guards and attachments are securely fixed, the correct guard is fitted for the cutting attachment in use, the blade is seated correctly, sharp and not cracked, and the retaining nut is secure.","The work sequence is organised so debris ejected by the saw flies into a safe zone; cutting stops immediately if anyone is seen within 15m. When cutting woody material where obstructions create a kickback risk, the operator uses the 8-11 o''clock sector of the blade.","Operators do not touch the cutting attachment while the engine is running and release the throttle if it becomes jammed."]'::jsonb, '["ppe_visor","ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_pedestrian_mowing', 'Grounds maintenance', 'Pedestrian Mowing', '["All PPE is worn prior to work commencing. The area to be mown is marked out with warning signs and safety tape if necessary.","Equipment is unloaded by rolling off the trailer/van, or lifted by two persons if from a van. The site is visually inspected and any debris removed before starting.","Equipment is visually inspected and removed from service if there are obvious faults. Safety features are checked and never defeated.","The site is kept clear of persons; mowing stops if this cannot be maintained. At completion the engine is stopped, the safety cut-off engaged, the key removed, and the mower cleaned down."]'::jsonb, '["ppe_hearing","ppe_visor"]'::jsonb, '[]'::jsonb),
  ('sop_ride_on_mower', 'Grounds maintenance', 'Ride on Mower', '["All PPE is worn prior to work commencing. The area to be mown is marked out with warning signs and safety tape if necessary, and visually inspected for debris beforehand.","Equipment is visually inspected and removed from service if there are obvious faults; safety features are checked and never defeated.","Cutting heads are kept level for a quality cut; if grass is long, the cutting height is raised so no more than 50% of the sward is cut at once, repeating as needed.","The site is kept clear of persons; mowing stops if this cannot be maintained. At completion the engine is stopped, the safety cut-off engaged, the key removed, and the mower cleaned down."]'::jsonb, '["ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_hedge_trimming', 'Grounds maintenance', 'Hedge Trimming', '["All PPE is worn prior to work commencing. The area to be trimmed is marked out with warning signs and safety tape if necessary.","Equipment is visually inspected and removed from service if any fault is found. Safety features are checked and never defeated.","The designated area is trimmed back to the previous cut, maintaining good horticultural practice. High areas are trimmed using long-arm cutters and, if required, tripod ladders.","At completion the trimmer is stopped, the safety cut-off activated, and the tool cleaned and returned to safe storage."]'::jsonb, '["ppe_visor","ppe_hearing"]'::jsonb, '[]'::jsonb),
  ('sop_weed_killing', 'Chemical', 'Weed Killing', '["Only City & Guilds/NPTC-qualified staff spray chemical on behalf of the company. Weed killer is kept in proprietary containers, clamped and secured in vans or lock boxes.","An environmental assessment for safe working is conducted before spraying (weather conditions, people/children in the vicinity, animals roaming loose).","The sprayer is filled and chemical mixed according to the label, in an isolated area on a surface that can contain a spillage. Weed killer is never sprayed in high-wind conditions or above knee height.","All chemical usage is recorded. If a spillage occurs, the COSHH assessment is followed, and weed killer is never left unattended or transferred to unmarked containers."]'::jsonb, '["ppe_coveralls","ppe_rubber_gloves","ppe_face_shield"]'::jsonb, '[]'::jsonb),
  ('sop_litter_picking', 'Grounds maintenance', 'Litter Picking', '["All litter picking equipment is stored in the vehicle lock box.","PPE — gloves, safety boots and safety glasses — is always worn.","Shrub beds are always checked for debris and sharps before entry; operators never walk through a shrub bed without being able to see where they are placing their foot."]'::jsonb, '["ppe_gloves","ppe_boots"]'::jsonb, '[]'::jsonb),
  ('sop_magni_crane', 'Machinery & plant', 'Magni RTH 6.31-VID (Truck-Mounted Crane / Grapple Saw)', '["Prior to use, the operator confirms the cutting head is correctly mounted on the carrier vehicle and that a test run of all functions is carried out. A visual leak test of the hydraulic system is also carried out.","The cutting head is only used to process woody material. Loose, broken or hanging limbs are, if practicable, dealt with first. Once cutting has commenced it is finished — partially cut trees are never left.","Taller and thicker trees are processed into short sections to prevent the carrier vehicle tipping. Prior to cutting, the operator estimates the weight of the section to be removed and consults the load ratings/lift plan to confirm it is within the rated capacity of the machine.","Cutting starts with the gripper opened all the way. The cutting head is aligned to the tree before cutting to obtain a straight cut. The gripper is closed, cutting takes place, and once complete the guide bar of the saw retracts into the saw unit.","Once cut, the operator moves the material to the set-down area.","When the machine is not in use, such as during breaks, it is parked on a load-bearing surface with the gripper closed and pressure relieved. The cutting head is lowered to the ground and the machine secured against unintentional start.","Post-works, dirt and foreign bodies are removed from the machine, lubrication is carried out, and any sharp components are covered.","During use, if the operator is unsure of any aspect of the lifting operation, they must immediately stop.","Stop work immediately if any form of malfunction occurs. The operator must be in good health and fit to carry out the required task, and their physical, mental or sensory capacities must not be impaired. The machine is never operated under the influence of drugs or alcohol.","On arrival on site, the operator ensures the correct PPE is worn for the site and liaises with the client or their representative.","The operator inspects the lifting area with the client to confirm its suitability, including for the machine to drive on and for stabiliser deployment. If not satisfied with the condition of the lifting or set-down/processing area, work does not proceed and the operator liaises with the client to address the issues raised.","Communication links and signalling methods between the operator and ground staff are confirmed.","The operator positions the machine.","The site supervisor ensures exclusion zones have been established.","Pre-use checks of the machine and attachments are carried out. The operator checks the load-sensing equipment and display are fully operational, confirming to the site supervisor that the machine is safe to operate.","The machine is set up, deploying stabiliser mats or pads as required.","The operator and site supervisor inspect what is to be cut, looking for insecure or broken material to be dealt with first.","The operator carries out dry runs to confirm the cutting attachment can reach the required height and radius, and that the route of the lift and processing areas are unobstructed.","The operator always operates the machine in accordance with the manufacturer''s guidance.","The cutting head is equipped with a powerful gripper used to ensure safe handling of the tree, with a saw unit — a chainsaw mounted in the lower part of the machine — used as the cutting instrument.","The operator checks that the machine is properly maintained and free from defect before use.","Report any damage or faults immediately."]'::jsonb, '["ppe_hearing"]'::jsonb, '["ez_excavator"]'::jsonb)
insert into ms_staff (id, name, default_role, first_aider, competencies) values
  ('s1', 'Jon Challinor', 'Managing Director and Arborist', true, '[{"name":"CSCS - Construction Skills Certification Scheme","expiry":null},{"name":"City & Guilds NPTC Cs30 - Chainsaw maintenance and crosscutting","expiry":null},{"name":"City & Guilds NPTC 31a, 31b - Fell and process small trees","expiry":null},{"name":"City & Guilds NPTC 38 - Climb trees and perform aerial rescue","expiry":null},{"name":"City & Guilds NPTC 39 - Use of a chainsaw from rope and harness","expiry":null},{"name":"CAT and Genny Training","expiry":null},{"name":"Emergency First Aid at Work","expiry":null},{"name":"Asbestos Awareness Training","expiry":null},{"name":"City & Guilds NPTC Level 2 use of Remote-controlled mower (flail)","expiry":null}]'::jsonb),
  ('s2', 'Dave Norris', 'Arborist and Site Supervisor', true, '[{"name":"CSCS - Construction Skills Certification Scheme","expiry":null},{"name":"CITB - Site Supervisors'' Safety Training Scheme (SSSTS)","expiry":null},{"name":"City & Guilds NPTC Cs30 - Chainsaw maintenance and crosscutting","expiry":null},{"name":"City & Guilds NPTC 31 - Fell and process small trees","expiry":null},{"name":"City & Guilds NPTC 38 - Climb trees and perform aerial rescue","expiry":null},{"name":"City & Guilds NPTC 39 - Use of a chainsaw from rope and harness","expiry":null},{"name":"City & Guilds NPTC Level 2 use of Remote-controlled mower (flail)","expiry":null},{"name":"City & Guilds NPTC Use of Manually Fed Chipper","expiry":null},{"name":"CAT and Genny Training","expiry":null},{"name":"FAA Level 3 in Emergency First Aid at Work","expiry":null},{"name":"FAA Level 3 in Forestry First Aid","expiry":null},{"name":"NPORS Tracked 1-10 tonnes 360-degree Excavator (log grab and flail attachments)","expiry":null},{"name":"ROLO Operative Health, Safety & Environmental Awareness Course","expiry":null},{"name":"Manual Handling","expiry":null},{"name":"Asbestos Awareness Training","expiry":null}]'::jsonb),
