insert into ms_fixed_sections (n, title, paragraphs) values
  ('11.0', 'Offloading Plant', '["Any vehicle or plant equipment used for unloading must be \"fit for purpose\", in accordance with the Provision and Use of Work Equipment Regulations and, where applicable, the Lifting Operations Lifting Equipment Regulations. Plant is subject to pre-use checks, recorded interim inspections and a periodic maintenance regime with defect reporting procedures in place.","Plant must only be offloaded into a safe area, such as a site compound or designated work area agreed by the contractor and client.","Offloading is only undertaken by individuals competent in the use of that machinery. Reversing of plant is kept to a minimum and under the direction of a banksperson.","Ramps are used strictly in accordance with manufacturer''s guidance — makeshift ramps are never used. Once offloaded, plant left unattended is isolated (keys removed)."]'::jsonb),
  ('12.0', 'Plant & Machinery Movements', '["Flashing beacons and warning lights, where fitted, are used on all vehicles and plant moving around site. Speed limits are set to a maximum of 5mph.","Tractors are escorted around the site with banksmen."]'::jsonb),
  ('13.0', 'At-Site Communication', '["A helmet-fitted radio communication system is used between operators."]'::jsonb),
  ('14.0', 'Welfare', '["The contractor''s own welfare vehicle is always on site, including hot and cold running water and toilet facilities."]'::jsonb),
  ('16.0', 'Evacuation Arrangements', '["Evacuation of team members will be through the access and egress point."]'::jsonb),
  ('17.0', 'Emergency Preparedness and Response Procedure', '["The purpose of this procedure is to establish a systematic approach to identify potential emergency situations, prepare for them, and ensure an effective response to minimise risk to personnel, customers, operations, and quality of products and services.","Refer to the company''s Emergency Preparedness and Response Procedure document."]'::jsonb),
  ('18.0', 'Environmental & Waste Management Arrangements — Air Quality', '["All plant and equipment is well maintained and regularly inspected to keep exhaust fumes and particulate matter to a minimum.","If a fault is identified, the plant is quarantined and repaired as required. No burning of waste materials takes place on site, and vehicles or plant are not left running when not in use."]'::jsonb),
  ('19.0', 'Archaeology and Cultural Heritage', '["N/a — no archaeological or cultural heritage considerations identified for this site."]'::jsonb),
  ('20.0', 'Ecology & Invasive Species', '["All reasonably practicable measures are taken to minimise harm to and disturbance of wildlife caused by noise, vibration, dust and light pollution.","A competent person carries out a wildlife and habitat assessment on specific trees identified. Habitat disturbance is reduced by keeping the extent of working areas to the minimum necessary.","The workforce is briefed on all ecological requirements and records retained. Where there is a conflict between operations and identified protected species, further ecological advice is sought."]'::jsonb),
  ('21.0', 'Energy Usage & Carbon Emissions', '["Plant operators switch off all plant and machinery when not in use, and report/quarantine any defect or malfunction until repaired.","Energy-efficient plant is chosen where practicable and maintained to maximise fuel efficiency, with maintenance records retained. Alternative energy sources — batteries rather than combustion engines — are preferred where available."]'::jsonb),
  ('22.0', 'Storage and Handling of Hazardous Substances and Materials (COSHH)', '["Fuels, oils and chemicals are stored in containers specifically manufactured for the purpose, clearly marked/labelled, and protected from impact damage.","Containers are placed on a plant nappy/spill tray during refuelling, with a spill kit or absorbent granules kept adjacent and to hand at all times.","Substances are purchased from reputable suppliers and used, stored and disposed of per supplier/manufacturer recommendations. COSHH assessments are carried out using the substance''s Material Safety Data Sheet, and operators are made aware of the assessment before use."]'::jsonb),
  ('23.0', 'Materials and Storage', '["All materials are securely stored to prevent breakage, vandalism and theft. Materials sensitive to the weather are protected and covered, and waste storage is kept separate from material storage."]'::jsonb),
  ('24.0', 'Noise & Vibration', '["Modern, silenced and well-maintained plant is always used, fitted with efficient attenuators, mufflers or acoustic covers where practicable, and expected to meet noise limit and marking requirements.","All operatives are provided hearing protection where noise levels are likely to exceed 80dB; where activities are known to exceed 85dB, hearing protection is mandatory and third parties are informed with an exclusion zone signed where necessary.","The vibration magnitude for each piece of vibratory equipment is obtained from the manufacturer and the maximum trigger time per 8-hour day relayed to operatives, supported by a data sheet to ensure recommended usage times are not exceeded. See Section 5.0 for the sound pressure and vibration data held for this company''s equipment."]'::jsonb),
  ('25.0', 'Waste Management Arrangements', '["Different waste streams are segregated to maximise reuse and recycling rates. Containers and skips are enclosed/secured to prevent waste escaping.","Hazardous waste is stored separately from inert and non-hazardous waste and not co-mingled with other hazardous waste, in suitable containment in a specific area.","Exemptions for storing waste on site are obtained as required, and all necessary environmental permits, exemptions and waste carrier licences are in place before work commences."]'::jsonb),
  ('26.0', 'Biosecurity', '["We as a company are committed to planning and managing our business activities to ensure the risk of introduction and spread of pests and diseases is kept to a minimum. Routine biosecurity control measures are undertaken as a minimum for all operations and worksites, with biosecurity risk assessment built into works planning. For sites identified as higher risk, specific biosecurity control measures are put in place."]'::jsonb),
  ('27.0', 'Briefing Arrangements', '["The site supervisor is responsible for briefing everyone on site on this method statement. Briefings are carried out before the start of each shift, with the opportunity given to all attendees to ask questions. Briefings and any queries raised are recorded as part of the briefing declaration."]'::jsonb),
  ('28.0', 'Monitoring of the Works', '["The company recognises the importance of health and safety inspection and auditing as a means of assessing the effective performance of the health and safety management system.","Periodic worksite and workplace safety inspections are co-ordinated by the Project Manager or their representative, with findings recorded, communicated to all management levels, and action points completed within the timeframe specified on the audit report."]'::jsonb),
  ('29.0', 'Handover and Hand back Arrangements', '["There are no handover requirements for the planned works."]'::jsonb)
insert into ms_known_hazards (hazard, control, sort_order) values
  ('Public — unauthorised site access', 'Works undertaken within a site signed and guarded on all reasonably foreseeable approaches.', 0),
  ('Strike to property — breakup of material', 'Control maintained to ensure branches cannot damage infrastructure. Trees subject to a visual tree assessment by a competent person.', 1),
  ('Flying debris', 'Machinery guarding in place.', 2),
  ('Tree felling', 'Visual assessment of tree condition carried out prior to felling. Felling and processing carried out by adequately trained, City & Guilds competent operators to FISA301-304. No lone working.', 3),
  ('Drop zones', 'Drop zones agreed and understood by all staff before work starts, with an agreed command/response communication protocol between aerial operator and groundstaff in place before starting work.', 4)
